<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Throwable;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableFilter;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableCursor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariableAttributes;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\List\TemplateVariableListUsecase;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

class TemplateVariableListController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateVariableListUsecase $listUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/document/template-variable",
        tags: ["Template variable"],
        description:"Create",
        responses: [
        new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateVariableApiListDTO")),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("List Template variable");
        $span = $this->startSpan("List Template variable");
        try {
            $params = $request->getQueryParams();
            $filter = new TemplateVariableFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                code: $params['code'] ?? null,
                tenant: isset($params['tenant']) ? new TenantRef($params['tenant']) : null,
                tenants: isset($params['tenants']) ? explode(",", $params['tenants']) : null,
            );
            $cursor = new TemplateVariableCursor(
                limit: (int)($params['limit'] ?? 100),
                sinceUid: $params['since-uid'] ?? null,
                sinceCode: $params['since-code'] ?? null,
                order: isset($params['order']) ? $this->extractOrder(explode(',', $params['order'])) : null,
            );
            $result = $this->listUsecase->list($filter, $cursor);
            $value = ['items' => array_map(fn (TemplateVariableAttributes $item): TemplateVariableApiDTO => $this->mapTemplateVariable($request, $item), $result->values())];
            $nextLink = $this->nextLink($result->cursor(), $params);
            if (null !== $nextLink) {
                $value['next'] = "?{$nextLink}";
            }
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function extractOrder(array $order): array
    {
        $this->logDebug("Extract order for Template variable");
        $span = $this->startSpan("Extract order for Template variable");
        try {
            $mapped = [];
            foreach ($order as $ord) {
                if ($ord === 'code-asc') {
                    $mapped[] = 'codeAsc';
                }
                if ($ord === 'code-desc') {
                    $mapped[] = 'codeDesc';
                }
            }
            return $mapped;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function nextLink(?TemplateVariableCursor $value, array $params): ?string
    {
        $this->logDebug("Check generic allow for Template variable");
        $span = $this->startSpan("Generic allow for Template variable");
        try {
            if (!$value) {
                return null;
            }
            $link = [];
            if (isset($params['limit'])) {
                $link['limit'] = 'limit=' . $params['limit'];
            }
            $sinceUid = $value->sinceUid();
            if (null !== $sinceUid) {
                $link['since-uid'] = 'since-uid=' . urlencode($sinceUid);
            }
            $sinceCode = $value->sinceCode();
            if (null !== $sinceCode &&  false !== strpos($params['order'] ?? '', 'CODE-ASC')) {
                $link['since-code'] = 'since-code=' . urlencode($sinceCode);
            }
            $sinceCode = $value->sinceCode();
            if (null !== $sinceCode &&  false !== strpos($params['order'] ?? '', 'CODE-DESC')) {
                $link['since-code'] = 'since-code=' . urlencode($sinceCode);
            }
            return implode('&', $link);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapTemplateVariable(ServerRequestInterface $request, TemplateVariableAttributes $value): TemplateVariableApiDTO
    {
        $this->logDebug("Map entity to output dto for Template variable");
        $span = $this->startSpan("Map entity to output dto for Template variable");
        try {
            $tenant = $value->getTenant();
            $dto = new TemplateVariableApiDTO();
            $dto->uid = $value->getUid();
            $dto->code = $value->getCode();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->type = $value->getType();
            $dto->value = $value->getValue();
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
